contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address accessControl) public {
        require(accessControl != address(0));

        bool firstReverted;
        try c.initialize(accessControl) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.initialize(accessControl) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(!firstReverted && secondReverted);
    }

    receive() external payable {}
}

