    function run(uint256 kink, uint256 slope0, uint256 slope1) public {
        bool initReverted;
        try c.initialize(address(this)) { initReverted = false; } catch { initReverted = true; }
        require(!initReverted);
        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({ kink: kink, slope0: slope0, slope1: slope1 });
        bool reverted;
        try c.setSlopes(address(this), slopes) { reverted = false; } catch { reverted = true; }
        assert(reverted == (kink == 0 || kink >= 1e27));
    }
}

