contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 maxMult, uint256 minMult, uint256 rate) public {
        bool reverted;
        // top-level state-changing call, revert observed via try is not allowed nested;
        // use low-level call to capture revert without nesting rules violation
        bytes memory data = abi.encodeWithSelector(c.setLimits.selector, maxMult, minMult, rate);
        (bool ok, ) = address(c).call(data);
        reverted = !ok;
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        // Grant ourselves access by making the access control this contract,
        // whose fallback returns true for checkAccess.
        c.initialize(address(this));

        bool reverted;
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == (kink == 0 || kink >= 1e27));
    }

    fallback() external payable returns (bool) {
        return true;
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        // Make this contract the access control so checkAccess succeeds via fallback.
        c.initialize(address(this));

        IVaultAdapter.SlopeData memory slopes =
            IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1});

        bool reverted;
        try c.setSlopes(asset, slopes) {
