        return abi.encode(true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint256 public util;

    constructor(C _c) { c = _c; }

    function run(address asset, uint256 u) public {
        util = u;

        bool reverted;
        uint256 out;
        try c.rate(address(this), asset) returns (uint256 v) {
            reverted = false;
            out = v;
        } catch {
            reverted = true;
        }

        // With all-zero slopes and zero stored multiplier/state on a fresh C:
        // utilization 0 hits division by the zero kink (revert),
        // any positive utilization yields an interest rate of exactly 0.
        assert((reverted == (u == 0)) && (reverted || out == 0));
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        // Serves IVault.currentUtilizationIndex / IVault.utilization.
        return abi.encode(util);
    }

    receive() external payable {}
}

